const birthdayItems = $input.all();
const slackUsers = $items('Get many users', 0, 0).map(i => i.json);
const slackDirectory = slackUsers.filter(u => u.profile && u.profile.email).map(u => ({ email: u.profile.email.trim().toLowerCase(), id: u.id, name: u.profile.real_name_normalized }));
const celebrants = [];
for (const emp of birthdayItems) {
  const email = (emp.json['Work Email '] || '').trim().toLowerCase();
  const slackMatch = slackDirectory.find(s => s.email === email);
  celebrants.push({ fullName: emp.json['Full Name'], email, slackId: slackMatch ? slackMatch.id : null });
}
return [{ json: { celebrants } }];
